     2	  RailError,
     3	  makeSettlementRef,
     4	  type Clock,
     5	  type PaymentRail,
     6	  type PaymentRequest,
     7	  type Quote,
     8	  type RailAuthorization,
     9	  type RailSettlement,
    10	  type Micros,
    11	} from '@mwb/core';
    12	
    13	/**
    14	 * A rail is a backend: quote → authorize → settle, all behind one
    15	 * interface. Field names inside `payload` are intentionally opaque — the
    16	 * specs churn (x402 v2, Cloudflare Pay Per Crawl are still being
    17	 * finalized), so the broker never parses them. Draft-caveat discipline:
    18	 * build against the interface, not a draft's field names.
    19	 */
    20	export interface RailBackend extends PaymentRail {}
    21	
    22	/**
    23	 * In-memory rail for tests, demos, and local dev. Mirrors the x402 shape
    24	 * (micro-unit price, `X-PAYMENT` header) without an external service.
    25	 * Deterministic: with a `frozenClock` and fixed input, the settlement
    26	 * reference is stable so reconciliation can be asserted.
    27	 */
    28	export class InMemoryRail implements PaymentRail {
    29	  readonly id: string;
    30	  readonly priceMicros: Micros;
    31	  readonly currency: string;
    32	  readonly clock: Clock;
    33	  private readonly settlementSeed: string = '';
    34	  private readonly failureMode: 'none' | 'quote' | 'authorize' | 'settle';
    35	
    36	  constructor(options: {
    37	    id: string;
    38	    priceMicros: Micros;
    39	    currency?: string;
    40	    clock?: Clock;
    41	    failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
    42	    /** Stable suffix seed so settlement refs are deterministic in tests. */
    43	    settlementSeed?: string;
    44	  }) {
    45	    this.id = options.id;
    46	    this.priceMicros = options.priceMicros;
    47	    this.currency = options.currency ?? 'USD';
    48	    this.clock = options.clock ?? { now: () => new Date().toISOString() };
    49	    this.failureMode = options.failureMode ?? 'none';
    50	    this.settlementSeed = options.settlementSeed ?? `${options.id}-seed`;
    51	  }
    52	
    53	  quote(_req: PaymentRequest): Promise<Quote> {
    54	    if (this.failureMode === 'quote') {
    55	      return Promise.reject(
    56	        new RailError(`${this.id}: quote failed`, 'RAIL_QUOTE', undefined, true)
    57	      );
    58	    }
    59	    const nowMs = Date.parse(this.clock.now());
    60	    return Promise.resolve({
    61	      unitsMicros: this.priceMicros,
    62	      currency: this.currency,
    63	      rail: this.id,
    64	      settlement: 'immediate',
    65	      expiresAt: new Date(nowMs + 60_000).toISOString(),
    66	    });
    67	  }
    68	
    69	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    70	    if (this.failureMode === 'authorize') {
    71	      return Promise.reject(
    72	        new RailError(`${this.id}: authorize failed`, 'RAIL_AUTHORIZE', undefined, true)
    73	      );
    74	    }
    75	    const payload = JSON.stringify({
    76	      schema: 'urn:rail:' + this.id,
    77	      amountMicros: quote.unitsMicros,
    78	      currency: quote.currency,
    79	      url: String(req.url),
    80	      method: req.method,
    81	    });
    82	    return Promise.resolve({
    83	      scheme: this.id,
    84	      payload,
    85	      settlementHeaders: { [`${this.id.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-payment`]: 'authorized' },
    86	    });
    87	  }
    88	
    89	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    90	    if (this.failureMode === 'settle') {
    91	      return Promise.reject(
    92	        new RailError(`${this.id}: settle failed`, 'RAIL_SETTLE', undefined, true)
    93	      );
    94	    }
    95	    const parsed = JSON.parse(authorization.payload) as { amountMicros: number; currency: string };
    96	    return Promise.resolve({
    97	      rail: this.id,
    98	      // Deterministic from (seed, url) so tests can assert reconciliation.
    99	      settlementRef: makeSettlementRef(this.id, deterministicRand(this.settlementSeed + String(req.url))),
   100	      amountMicros: parsed.amountMicros,
   101	      currency: parsed.currency,
   102	      settledAt: this.clock.now(),
   103	    });
   104	  }
   105	}
   106	
   107	/** Self-hosted 402 rail: same interface, different origin. */
   108	export class SelfHosted402Rail extends InMemoryRail {
   109	  constructor(options: { priceMicros: Micros; clock?: Clock; tenantId?: string }) {
   110	    super({
   111	      id: 'self402',
   112	      priceMicros: options.priceMicros,
   113	      clock: options.clock,
   114	      settlementSeed: `self402-${options.tenantId ?? 'tenant'}`,
   115	    });
   116	    this._tenantId = options.tenantId;
   117	  }
   118	  private _tenantId?: string;
   119	  tenantId(): string | undefined {
   120	    return this._tenantId;
   121	  }
   122	}
   123	
   124	/**
   125	 * Wraps an existing bridge client (e.g. an ap2-x402-bridge or AP2
   126	 * rail-adapter-x402 instance) so it can be used as a rail. The broker sees
   127	 * only this minimal shape — it does not depend on the bridge's own types.
   128	 * That is the "one contract" boundary in practice.
   129	 */
   130	export interface BridgeClientShape {
   131	  quote(input: { url: string; method: string; headers: Record<string, string> }): Promise<Quote>;
   132	  authorize(input: {
   133	    url: string;
   134	    method: string;
   135	    headers: Record<string, string>;
   136	    quote: { unitsMicros: number; currency: string };
   137	  }): Promise<RailAuthorization>;
   138	  settle(input: {
   139	    url: string;
   140	    method: string;
   141	    headers: Record<string, string>;
   142	    authorization: RailAuthorization;
   143	  }): Promise<RailSettlement>;
   144	}
   145	
   146	export class BridgeRail implements PaymentRail {
   147	  constructor(
   148	    private readonly idAndBridge: { id: string; bridge: BridgeClientShape }
   149	  ) {}
   150	
   151	  get id(): string {
   152	    return this.idAndBridge.id;
   153	  }
   154	
   155	  quote(req: PaymentRequest): Promise<Quote> {
   156	    return this.idAndBridge.bridge.quote({ url: String(req.url), method: req.method, headers: req.headers });
   157	  }
   158	
   159	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   160	    return this.idAndBridge.bridge.authorize({
   161	      url: String(req.url),
   162	      method: req.method,
   163	      headers: req.headers,
   164	      quote: { unitsMicros: quote.unitsMicros, currency: quote.currency },
   165	    });
   166	  }
   167	
   168	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
   169	    return this.idAndBridge.bridge.settle({
   170	      url: String(req.url),
   171	      method: req.method,
   172	      headers: req.headers,
   173	      authorization,
   174	    });
   175	  }
   176	}
   177	
   178	/** Registry lets the broker pick a rail per URL/tenant without touching the agent. */
   179	export class RailRegistry {
   180	  private readonly rails = new Map<string, PaymentRail>();
   181	
   182	  register(rail: PaymentRail): this {
   183	    if (this.rails.has(rail.id)) {
   184	      throw new RailError(`Rail already registered: ${rail.id} (deregister first)`, 'RAIL_REGISTER');
   185	    }
   186	    this.rails.set(rail.id, rail);
   187	    return this;
   188	  }
   189	
   190	  deregister(id: string): boolean {
   191	    return this.rails.delete(id);
   192	  }
   193	
   194	  get(id: string): PaymentRail {
   195	    const r = this.rails.get(id);
   196	    if (!r) throw new RailError(`No rail registered: ${id}`, 'RAIL_MISSING');
   197	    return r;
   198	  }
   199	
   200	  /** Look up a rail by id without throwing when it is absent. */
   201	  optional(id: string): PaymentRail | undefined {
   202	    return this.rails.get(id);
   203	  }
   204	
   205	  ids(): string[] {
   206	    return [...this.rails.keys()].sort();
   207	  }
   208	}
   209	
   210	/** Deterministic PRNG from a seed (FNV-1a based) so settlement refs are stable in tests. */
   211	function deterministicRand(seed: string): () => number {
   212	  let h = 2166136261;
   213	  for (let i = 0; i < seed.length; i++) {
   214	    h ^= seed.charCodeAt(i);
   215	    h = Math.imul(h, 16777619);
   216	  }
   217	  return () => {
   218	    h += 0x6d2b79f5;
   219	    let t = h;
   220	    t = Math.imul(t ^ (t >>> 15), t | 1);
   221	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
   222	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
   223	  };
   224	}"}

